optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/host.rs b/tools/bot-evaluation/src/host.rs
index 4593133d..d6f9a2d0 100644
--- a/tools/bot-evaluation/src/host.rs
+++ b/tools/bot-evaluation/src/host.rs
@@ -68,7 +68,8 @@ impl Host {
         })
     }
     pub fn send(&mut self, v: &Value) -> Result<()> {
-        serde_json::to_writer(&mut self.input, v)?;
+        let bytes = serde_json::to_vec(v)?;
+        self.input.write_all(&bytes)?;
         self.input.write_all(b"\n")?;
         self.input.flush()?;
         Ok(())
